import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import './App.css'

const players = [
    { rank: 1, name: "Alex", score: 2560, accuracy: 96, quizzes: 24 },
    { rank: 2, name: "Sara", score: 2340, accuracy: 94, quizzes: 22 },
    { rank: 3, name: "Ahmed", score: 2210, accuracy: 92, quizzes: 21 },
    { rank: 4, name: "John", score: 2050, accuracy: 91, quizzes: 20 },
    { rank: 5, name: "You", score: 1980, accuracy: 89, quizzes: 19 },
    { rank: 6, name: "Maria", score: 1920, accuracy: 87, quizzes: 18 },
    { rank: 7, name: "David", score: 1850, accuracy: 85, quizzes: 17 },
    { rank: 8, name: "James", score: 1760, accuracy: 84, quizzes: 16 },
];

export function Leaderboard() {
    const [activeTab, setActiveTab] = useState("All Time");

    const topThree = players.slice(0, 3);
    const remainingPlayers = players.slice(3);
    const location = useLocation()
    // for the space background
    useEffect(() => {
        if (location.pathname !== "/leaderboard") return;
        const starsContainer = document.getElementById("stars");

        if (!starsContainer) return;    
        starsContainer.innerHTML = "";

        for (let i = 0; i < 180; i++) {
            const star = document.createElement("div");

            const size =
                Math.random() > 0.96
                    ? "lg"
                    : Math.random() > 0.7
                        ? "md"
                        : "sm";

            star.className = `star ${size}`;

            star.style.left = Math.random() * 100 + "%";
            star.style.top = Math.random() * 100 + "%";

            star.style.animationDuration =
                2 + Math.random() * 6 + "s";

            star.style.animationDelay =
                Math.random() * 5 + "s";

            starsContainer.appendChild(star);
        }
    }, [location.pathname]);
    return (
        <div className="container py-5">
            <div id ='stars'></div>
            {/* Header */}
            <div className="text-center mb-4">
                <h1 className=" text-white fw-bold">
                    🏆 Quiz Leaderboard
                </h1>
                <p className="text-white">
                    See how you rank against other players
                </p>
            </div>

            {/* Tabs */}
            {/* <div className="d-flex justify-content-center mb-5">
                <div className="btn-group">
                    {["Today", "This Week", "All Time"].map((tab) => (
                        <button
                            key={tab}
                            className={`btn ${activeTab === tab
                                    ? "btn-primary"
                                    : "btn-outline-primary"
                                }`}
                            onClick={() => setActiveTab(tab)}
                        >
                            {tab}
                        </button>
                    ))}
                </div>
            </div> */}

            {/* Top 3 */}
            <div className="row justify-content-center align-items-end g-4 mb-5">
                {/* Second Place */}
                <div className="col-10 col-md-3">
                    <div className="card border-0 shadow text-center">
                        <div className="card-body">
                            <div className="fs-1">🥈</div>

                            <div
                                className="rounded-circle bg-secondary text-white d-flex
                align-items-center justify-content-center mx-auto mb-3"
                                style={{ width: "70px", height: "70px", fontSize: "25px" }}
                            >
                                {topThree[1].name.charAt(0)}
                            </div>

                            <h5 className="fw-bold">{topThree[1].name}</h5>

                            <h4 className="text-primary fw-bold">
                                {topThree[1].score.toLocaleString()}
                            </h4>

                            <small className="text-muted">points</small>
                        </div>
                    </div>
                </div>

                {/* First Place */}
                <div className="col-10 col-md-3">
                    <div className="card border-primary bg-dark border-3 shadow-lg text-center">
                        <div className="card-body">
                            <div className="fs-1">🥇</div>

                            <div
                                className="rounded-circle bg-warning text-dark d-flex
                align-items-center justify-content-center mx-auto mb-3"
                                style={{ width: "85px", height: "85px", fontSize: "30px" }}
                            >
                                {topThree[0].name.charAt(0)}
                            </div>

                            <h4 className="fw-bold">{topThree[0].name}</h4>

                            <h3 className="text-warning fw-bold">
                                {topThree[0].score.toLocaleString()}
                            </h3>

                            <small className="text-muted">points</small>
                        </div>
                    </div>
                </div>

                {/* Third Place */}
                <div className="col-10 col-md-3">
                    <div className="card border-0 shadow text-center">
                        <div className="card-body">
                            <div className="fs-1">🥉</div>

                            <div
                                className="rounded-circle bg-danger text-white d-flex
                align-items-center justify-content-center mx-auto mb-3"
                                style={{ width: "70px", height: "70px", fontSize: "25px" }}
                            >
                                {topThree[2].name.charAt(0)}
                            </div>

                            <h5 className="fw-bold">{topThree[2].name}</h5>

                            <h4 className="text-primary fw-bold">
                                {topThree[2].score.toLocaleString()}
                            </h4>

                            <small className="text-muted">points</small>
                        </div>
                    </div>
                </div>
            </div>

            {/* Leaderboard Table */}
            <div className="card border-0 shadow">
                <div className="card-body p-0">
                    <div className="table-responsive">
                        <table className="table table-hover align-middle mb-0">
                            <thead className="table-dark">
                                <tr>
                                    <th className="ps-4">Rank</th>
                                    <th>Player</th>
                                    <th>Score</th>
                                    <th>Accuracy</th>
                                    <th>Quizzes</th>
                                </tr>
                            </thead>

                            <tbody>
                                {remainingPlayers.map((player) => (
                                    <tr
                                        key={player.rank}
                                        className={
                                            player.name === "You" ? "table-primary fw-bold" : ""
                                        }
                                    >
                                        <td className="ps-4">
                                            <span className="badge bg-secondary rounded-pill">
                                                #{player.rank}
                                            </span>
                                        </td>

                                        <td>
                                            <div className="d-flex align-items-center">
                                                <div
                                                    className="rounded-circle bg-primary text-white
                          d-flex align-items-center justify-content-center
                          me-3"
                                                    style={{
                                                        width: "40px",
                                                        height: "40px",
                                                    }}
                                                >
                                                    {player.name.charAt(0)}
                                                </div>

                                                {player.name}

                                                {player.name === "You" && (
                                                    <span className="badge bg-success ms-2">
                                                        You
                                                    </span>
                                                )}
                                            </div>
                                        </td>

                                        <td>
                                            <span className="fw-bold text-primary">
                                                {player.score.toLocaleString()}
                                            </span>
                                        </td>

                                        <td>
                                            <span className="badge bg-success">
                                                {player.accuracy}%
                                            </span>
                                        </td>

                                        <td>{player.quizzes}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
}
